SELECT "ERROR_CATEGORY" AS "ERROR_CATEGORY", COUNT(*) AS count 
FROM "default"."jobs" 
WHERE "@timestamp_date" >= TIMESTAMP '2026-03-25 00:00:00.000000' AND "@timestamp_date" < TIMESTAMP '2026-04-02 00:00:00.000000' AND ("ERROR_DESCRIPTION" ILIKE '%step 4%') GROUP BY "ERROR_CATEGORY" 
HAVING (COUNT(*) > 10) ORDER BY count DESC 
 LIMIT 100;